  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Acamprosate, a small polar molecule with an acidic group and amide, has a low absolute oral bioavailability of 11 ± 1% in humans, supporting low F for the similarly polar, acidic query.",
